function numberOfArithmeticSlices(nums) {
  let count = 0;
  // From each start, grow the subarray while its steps all equal the first step.
  for (let start = 0; start + 2 < nums.length; start++) {
    const step = nums[start + 1] - nums[start];
    for (let end = start + 2; end < nums.length; end++) {
      if (nums[end] - nums[end - 1] !== step) break;
      count++;
    }
  }
  return count;
}

