function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(12);
  const nums = [];
  // Mix random values with arithmetic runs whose step keeps them inside [-1000, 1000].
  while (nums.length < n) {
    if (rand() < 0.5) {
      nums.push(size === 'large' ? pick(2001) - 1000 : pick(7) - 3);
      continue;
    }
    const length = Math.min(n - nums.length, 2 + pick(size === 'large' ? 400 : 6));
    const step = pick(size === 'large' && rand() < 0.5 ? 5 : 3) - (size === 'large' && rand() < 0.5 ? 2 : 1);
    const span = Math.abs(step) * (length - 1);
    let value = pick(2001 - span) - 1000 + (step < 0 ? span : 0);
    for (let k = 0; k < length; k++) {
      nums.push(value);
      value += step;
    }
  }
  return [nums];
}
